insert into public.learning_cards (lesson_id, position, title, blocks) values ('a04a4936-0ba2-52ac-9795-850c5d474178', 1, 'La défaite des Gaulois', '[{"type":"keyfigure","value":"52 av. J.-C.","label":"Bataille d’Alésia"},{"type":"text","text":"Vercingétorix, chef gaulois, se rend à Jules César après le siège d’Alésia. La Gaule devient romaine pour près de cinq siècles."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('a04a4936-0ba2-52ac-9795-850c5d474178', 2, 'Un empereur à Noël', '[{"type":"text","text":"Le 25 décembre 800, à Rome, le pape couronne Charlemagne empereur. Son empire couvre une grande partie de l’Europe de l’Ouest."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('a04a4936-0ba2-52ac-9795-850c5d474178', 3, 'La Pucelle d’Orléans', '[{"type":"text","text":"En pleine guerre de Cent Ans contre les Anglais, Jeanne d’Arc délivre Orléans en 1429 et fait sacrer Charles VII à Reims. Capturée, elle est brûlée à Rouen en 1431."}]'::jsonb);
