insert into public.learning_cards (lesson_id, position, title, blocks) values ('5a6496a6-b733-5fa4-afe5-0bbd1aeafa91', 1, 'L’Empereur', '[{"type":"text","text":"Général devenu Premier consul, Napoléon Bonaparte se sacre empereur à Notre-Dame de Paris en 1804. Après des années de conquêtes, il est battu à Waterloo en 1815 et exilé à Sainte-Hélène."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('5a6496a6-b733-5fa4-afe5-0bbd1aeafa91', 2, '1848, année des droits', '[{"type":"list","items":["Abolition de l’esclavage, portée par Victor Schœlcher.","Suffrage universel masculin : tous les hommes peuvent voter."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('5a6496a6-b733-5fa4-afe5-0bbd1aeafa91', 3, 'La laïcité', '[{"type":"text","text":"En 1905, une loi sépare les Églises et l’État. L’État ne reconnaît ni ne finance aucun culte, mais garantit la liberté de conscience."}]'::jsonb);
